-- 028_print_sales_discounts.sql
-- Sales discounts (BUSINESS_RULES 13C), part 2 of 2: printing, photocopying and other Shop services. GENERATED by
-- server/src/db/gen/sales-discounts-sql.ts; do not edit.
-- Rebuilds print_sales because its table CHECK (revenue_cents = qty * unit_price_cents AND cogs_cents = qty * unit_cost_cents) must become
--   revenue = qty x unit_price - line_discount - bill_discount, and still cogs = qty x unit_cost
-- and SQLite cannot alter a table CHECK. Adds the same five NOT NULL columns as 027 (list_unit_price_cents = unit_price_cents and the four
-- discount columns 0 for every existing row), with the same CHECKs (plus revenue_cents >= 0). Every other column value, id and the
-- AUTOINCREMENT counter are preserved exactly. print_sales is Shop-only by construction (no Telecom form), so it needs no Telecom trigger.
-- Same technique and guards as 027: TEMP copy, DROP, CREATE, re-insert with the same ids, EVERY index and trigger re-created verbatim from a
-- schema-26 database (trg_print_sales_immutable also covers the new columns), plus the compatibility trigger
-- trg_print_sales_list_price_default (see 027). The migration aborts (rolls back) if any row differs, a foreign key is broken, the set of
-- indexes and triggers is not exactly the old set plus the new trigger, or ANY object outside print_sales (the cash-entry triggers keyed on
-- ref_table = 'print_sales', the corrections link ...) changed. print_sales has no foreign-key children; its parent print_service_types is untouched.

PRAGMA defer_foreign_keys = ON;

-- everything the migration must leave alone, and every object of the table that must come back
CREATE TEMP TABLE _mig028_other AS
SELECT type, name, tbl_name, sql FROM sqlite_master WHERE tbl_name <> 'print_sales' AND name NOT LIKE 'sqlite_%';
CREATE TEMP TABLE _mig028_objs AS
SELECT type, name, tbl_name FROM sqlite_master
 WHERE tbl_name = 'print_sales' AND type IN ('index','trigger') AND name NOT LIKE 'sqlite_autoindex%';

CREATE TEMP TABLE _mig028_rows AS SELECT id, business_date, posted_at, service_type_id, description, qty, unit_price_cents, unit_cost_cents, revenue_cents, cogs_cents, status, voided_at, void_reason, notes, client_ref FROM print_sales;
CREATE TEMP TABLE _mig028_seq AS SELECT COALESCE((SELECT seq FROM sqlite_sequence WHERE name = 'print_sales'), 0) AS seq;

DROP TABLE print_sales;

CREATE TABLE print_sales (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  business_date    TEXT    NOT NULL,
  posted_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  service_type_id  INTEGER NOT NULL REFERENCES print_service_types(id),
  description      TEXT    NOT NULL,
  qty              INTEGER NOT NULL CHECK (qty BETWEEN 1 AND 1000000),
  unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents BETWEEN 0 AND 1000000000),
  unit_cost_cents  INTEGER NOT NULL CHECK (unit_cost_cents BETWEEN 0 AND 1000000000),
  revenue_cents    INTEGER NOT NULL,
  cogs_cents       INTEGER NOT NULL,
  status           TEXT    NOT NULL DEFAULT 'posted' CHECK (status IN ('posted','void')),
  voided_at        TEXT,
  void_reason      TEXT,
  notes            TEXT    NOT NULL DEFAULT '',
  client_ref       TEXT    NOT NULL UNIQUE,
  list_unit_price_cents INTEGER NOT NULL DEFAULT -1 CHECK (list_unit_price_cents >= -1),
  unit_discount_cents   INTEGER NOT NULL DEFAULT 0 CHECK (unit_discount_cents >= 0),
  line_discount_cents   INTEGER NOT NULL DEFAULT 0 CHECK (line_discount_cents >= 0),
  price_reduction_cents INTEGER NOT NULL DEFAULT 0 CHECK (price_reduction_cents >= 0),
  bill_discount_cents   INTEGER NOT NULL DEFAULT 0 CHECK (bill_discount_cents >= 0),
  -- real calendar date only (GLOB checks the shape, date() rejects 31 February; IS NOT NULL also rejects month 13, because date() answers NULL and a NULL CHECK would pass)
  CHECK (business_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND date(business_date) IS NOT NULL AND date(business_date) = business_date),
  CHECK (length(trim(description)) > 0),
  -- the cost of a sale is exactly quantity x unit cost (no rounding exists here); what was paid is the gross amount minus the discounts
  CHECK (cogs_cents = qty * unit_cost_cents),
  CHECK (revenue_cents >= 0),
  -- section 13C: the amount paid is the gross line minus the per-unit discounts minus the line's share of the whole-bill discount
  CHECK (revenue_cents = qty * unit_price_cents - line_discount_cents - bill_discount_cents),
  CHECK (unit_discount_cents <= unit_price_cents),
  CHECK (line_discount_cents = unit_discount_cents * qty),
  -- the automatic price reduction: typed price below the list price (a higher typed price is an ordinary price, no reduction)
  CHECK (price_reduction_cents = qty * CASE WHEN list_unit_price_cents > unit_price_cents THEN list_unit_price_cents - unit_price_cents ELSE 0 END),
  -- a void always records when and why; a posted sale never has them
  CHECK (status = 'posted' OR (voided_at IS NOT NULL AND void_reason IS NOT NULL)),
  CHECK (status = 'void' OR (voided_at IS NULL AND void_reason IS NULL))
);

-- the triggers are re-created only after the copy, so none of them fires while the rows are copied back
INSERT INTO print_sales (id, business_date, posted_at, service_type_id, description, qty, unit_price_cents, unit_cost_cents, revenue_cents, cogs_cents, status, voided_at, void_reason, notes, client_ref, list_unit_price_cents, unit_discount_cents, line_discount_cents, price_reduction_cents, bill_discount_cents)
SELECT id, business_date, posted_at, service_type_id, description, qty, unit_price_cents, unit_cost_cents, revenue_cents, cogs_cents, status, voided_at, void_reason, notes, client_ref, unit_price_cents, 0, 0, 0, 0 FROM _mig028_rows ORDER BY id;

UPDATE sqlite_sequence SET seq = max(seq, (SELECT seq FROM _mig028_seq)) WHERE name = 'print_sales';

-- ===== indexes and triggers of schema 26 (verbatim; only the immutable trigger is extended) =====
CREATE INDEX idx_print_sales_business_date ON print_sales(business_date);

CREATE INDEX idx_print_sales_posted_at ON print_sales(posted_at);

CREATE INDEX idx_print_sales_type_date ON print_sales(service_type_id, business_date);

CREATE TRIGGER trg_print_sales_business_date_immutable
BEFORE UPDATE OF business_date ON print_sales
WHEN NEW.business_date <> OLD.business_date
BEGIN
  SELECT RAISE(ABORT, 'BUSINESS_DATE_IMMUTABLE');
END;

CREATE TRIGGER trg_print_sales_day_closed
BEFORE INSERT ON print_sales
WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'shop' AND d.business_date >= NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'shop' AND d.business_date = NEW.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
    THEN RAISE(ABORT, 'DAY_CLOSED')
    ELSE RAISE(ABORT, 'BACKDATE_BEFORE_CLOSED_DAY')
  END;
END;

CREATE TRIGGER trg_print_sales_day_closed_void
BEFORE UPDATE OF status ON print_sales
WHEN OLD.status = 'posted' AND NEW.status = 'void'
  AND EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'shop' AND d.business_date >= OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM daily_closings d WHERE d.book = 'shop' AND d.business_date = OLD.business_date AND (d.reopened_at IS NULL OR d.closed_at > d.reopened_at))
    THEN RAISE(ABORT, 'DAY_CLOSED')
    ELSE RAISE(ABORT, 'BACKDATE_BEFORE_CLOSED_DAY')
  END;
END;

CREATE TRIGGER trg_print_sales_future_date
BEFORE INSERT ON print_sales
WHEN NEW.business_date > date('now','+330 minutes')
BEGIN
  SELECT RAISE(ABORT, 'FUTURE_DATE_NOT_ALLOWED');
END;

CREATE TRIGGER trg_print_sales_immutable
BEFORE UPDATE OF id, service_type_id, description, qty, unit_price_cents, unit_cost_cents, revenue_cents, cogs_cents,
                 list_unit_price_cents, unit_discount_cents, line_discount_cents, price_reduction_cents, bill_discount_cents,
                 notes, client_ref, status, voided_at, void_reason ON print_sales
WHEN NEW.id IS NOT OLD.id
  OR NEW.service_type_id IS NOT OLD.service_type_id
  OR NEW.description IS NOT OLD.description
  OR NEW.qty IS NOT OLD.qty
  OR NEW.unit_price_cents IS NOT OLD.unit_price_cents
  OR NEW.unit_cost_cents IS NOT OLD.unit_cost_cents
  OR NEW.revenue_cents IS NOT OLD.revenue_cents
  OR NEW.cogs_cents IS NOT OLD.cogs_cents
  OR NEW.unit_discount_cents IS NOT OLD.unit_discount_cents
  OR NEW.line_discount_cents IS NOT OLD.line_discount_cents
  OR NEW.price_reduction_cents IS NOT OLD.price_reduction_cents
  OR NEW.bill_discount_cents IS NOT OLD.bill_discount_cents
  OR (NEW.list_unit_price_cents IS NOT OLD.list_unit_price_cents
      AND NOT (OLD.list_unit_price_cents = -1 AND NEW.list_unit_price_cents = OLD.unit_price_cents))
  OR NEW.notes IS NOT OLD.notes
  OR NEW.client_ref IS NOT OLD.client_ref
  OR (OLD.status = 'void' AND (NEW.status IS NOT OLD.status
        OR NEW.voided_at IS NOT OLD.voided_at OR NEW.void_reason IS NOT OLD.void_reason))
  OR (OLD.status = 'posted' AND NEW.status = 'posted'
        AND (NEW.voided_at IS NOT OLD.voided_at OR NEW.void_reason IS NOT OLD.void_reason))
BEGIN
  SELECT RAISE(ABORT, 'PRINT_SALE_IMMUTABLE');
END;

CREATE TRIGGER trg_print_sales_no_delete
BEFORE DELETE ON print_sales
BEGIN
  SELECT RAISE(ABORT, 'RECORD_DELETE_FORBIDDEN');
END;

CREATE TRIGGER trg_print_sales_posted_at_immutable
BEFORE UPDATE OF posted_at ON print_sales
WHEN NEW.posted_at IS NOT OLD.posted_at
BEGIN
  SELECT RAISE(ABORT, 'POSTED_AT_IMMUTABLE');
END;

CREATE TRIGGER trg_print_sales_type_active
BEFORE INSERT ON print_sales
WHEN (SELECT active FROM print_service_types WHERE id = NEW.service_type_id) = 0
BEGIN
  SELECT RAISE(ABORT, 'SERVICE_TYPE_INACTIVE');
END;

CREATE TRIGGER trg_print_sales_void_requires_reversal
BEFORE UPDATE OF status ON print_sales
WHEN OLD.status <> 'void' AND NEW.status = 'void' AND NEW.voided_at IS NOT NULL AND NEW.void_reason IS NOT NULL
 AND (
    EXISTS (SELECT 1 FROM cash_entries o
             WHERE o.ref_table = 'print_sales' AND o.ref_id = OLD.id AND o.reverses_entry_id IS NULL AND o.amount_cents <> 0
               AND NOT EXISTS (SELECT 1 FROM cash_entries r
                                WHERE r.reverses_entry_id = o.id AND r.amount_cents = -o.amount_cents AND r.book = o.book
                                  AND r.fund IS o.fund AND r.business_date = o.business_date))
    OR EXISTS (SELECT 1 FROM stock_movements o
                WHERE o.ref_table = 'print_sales' AND o.ref_id = OLD.id AND o.reverses_movement_id IS NULL
                  AND NOT EXISTS (SELECT 1 FROM stock_movements r WHERE r.reverses_movement_id = o.id)
                  AND NOT (o.type = 'adjustment' AND o.qty_delta = 0 AND o.value_delta_cents < 0
                           AND EXISTS (SELECT 1 FROM stock_movements c
                                        WHERE c.ref_table = o.ref_table AND c.ref_id = o.ref_id AND c.product_id = o.product_id
                                          AND c.reverses_movement_id IS NOT NULL AND c.id > o.id)))
    OR EXISTS (SELECT 1 FROM icecream_fund_entries o
                WHERE o.ref_table = 'print_sales' AND o.ref_id = OLD.id AND o.reverses_entry_id IS NULL
                  AND NOT EXISTS (SELECT 1 FROM icecream_fund_entries r
                                   WHERE r.reverses_entry_id = o.id AND r.amount_cents = -o.amount_cents AND r.fund = o.fund
                                     AND r.business_date = o.business_date))
 )
BEGIN
  SELECT RAISE(ABORT, 'VOID_WITHOUT_REVERSAL');
END;

-- ===== new objects =====
-- compatibility: a sale inserted without a list price (the -1 default) is sold at its own price
CREATE TRIGGER trg_print_sales_list_price_default
AFTER INSERT ON print_sales
WHEN NEW.list_unit_price_cents = -1
BEGIN
  UPDATE print_sales SET list_unit_price_cents = NEW.unit_price_cents WHERE id = NEW.id;
END;

-- ===== guard: any difference aborts (and so rolls back) the whole migration =====
CREATE TEMP TABLE _mig028_new (name TEXT NOT NULL);
INSERT INTO _mig028_new VALUES ('trg_print_sales_list_price_default');
CREATE TEMP TABLE _mig028_guard (ok INTEGER NOT NULL CHECK (ok = 1));
INSERT INTO _mig028_guard SELECT CASE WHEN
  (SELECT COUNT(*) FROM print_sales) = (SELECT COUNT(*) FROM _mig028_rows)
 AND   NOT EXISTS (SELECT 1 FROM _mig028_rows o LEFT JOIN print_sales n ON n.id = o.id WHERE n.id IS NULL
                      OR n.id IS NOT o.id
                      OR n.business_date IS NOT o.business_date
                      OR n.posted_at IS NOT o.posted_at
                      OR n.service_type_id IS NOT o.service_type_id
                      OR n.description IS NOT o.description
                      OR n.qty IS NOT o.qty
                      OR n.unit_price_cents IS NOT o.unit_price_cents
                      OR n.unit_cost_cents IS NOT o.unit_cost_cents
                      OR n.revenue_cents IS NOT o.revenue_cents
                      OR n.cogs_cents IS NOT o.cogs_cents
                      OR n.status IS NOT o.status
                      OR n.voided_at IS NOT o.voided_at
                      OR n.void_reason IS NOT o.void_reason
                      OR n.notes IS NOT o.notes
                      OR n.client_ref IS NOT o.client_ref
                      OR n.list_unit_price_cents IS NOT o.unit_price_cents
                      OR n.unit_discount_cents IS NOT 0
                      OR n.line_discount_cents IS NOT 0
                      OR n.price_reduction_cents IS NOT 0
                      OR n.bill_discount_cents IS NOT 0)
 AND   (SELECT seq FROM sqlite_sequence WHERE name = 'print_sales') >= (SELECT seq FROM _mig028_seq)
 AND   NOT EXISTS (SELECT 1 FROM pragma_foreign_key_check)
 AND   NOT EXISTS (SELECT 1 FROM _mig028_objs o WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.type = o.type AND m.name = o.name AND m.tbl_name = o.tbl_name))
 AND   NOT EXISTS (SELECT 1 FROM _mig028_new w WHERE NOT EXISTS (SELECT 1 FROM sqlite_master m WHERE m.type = 'trigger' AND m.name = w.name AND m.tbl_name = 'print_sales'))
 AND   (SELECT COUNT(*) FROM sqlite_master WHERE tbl_name = 'print_sales' AND type IN ('index','trigger') AND name NOT LIKE 'sqlite_autoindex%') = (SELECT COUNT(*) FROM _mig028_objs) + (SELECT COUNT(*) FROM _mig028_new)
 AND   (SELECT COUNT(*) FROM sqlite_master WHERE tbl_name <> 'print_sales' AND name NOT LIKE 'sqlite_%') = (SELECT COUNT(*) FROM _mig028_other)
 AND   NOT EXISTS (SELECT 1 FROM _mig028_other o LEFT JOIN sqlite_master m ON m.type = o.type AND m.name = o.name WHERE m.name IS NULL OR m.tbl_name IS NOT o.tbl_name OR m.sql IS NOT o.sql)
  THEN 1 ELSE 0 END;

DROP TABLE _mig028_guard;
